structs.GFC:
struct GFC
{
    uint64_t M;
    uint64_t r;
    uint64_t a;
    uint64_t b;
    uint32_t *speck_exp;
}

functions.speck_encrypt:
void speck_encrypt(uint32_t const pt[2], uint32_t ct[2], uint32_t const K[27])
{
    uint32_t i;
    ct[0] = pt[0];
    ct[1] = pt[1];
    for (i = 0; i < 27; i++)
    {
        (ct[1] = ((ct[1] >> 8) | (ct[1] << ((sizeof(uint32_t) * 8) - 8))), ct[1] += ct[0], ct[1] ^= K[i],
         ct[0] = ((ct[0] << 3) | (ct[0] >> ((sizeof(uint32_t) * 8) - 3))), ct[0] ^= ct[1]);
    }
}

functions.F:
uint64_t F(const GFC *gfc, const uint64_t j, const uint64_t R)
{
    uint64_t enc;
    const uint32_t *key = gfc->speck_exp + (j - 1) * 27;
    speck_encrypt((const uint32_t *)&R, (uint32_t *)&enc, key);
    return enc;
}

functions.fe:
uint64_t fe(const GFC *gfc, const uint64_t m)
{
    uint64_t L, R, tmp;
    L = m % gfc->a;
    R = m / gfc->a;
    for (uint64_t j = 1; j <= gfc->r; j++)
    {
        if (j & 1)
        {
            tmp = (L + F(gfc, j, R)) % gfc->a;
        }
        else
        {
            tmp = (L + F(gfc, j, R)) % gfc->b;
        }
        L = R;
        R = tmp;
    }
    if (gfc->r & 1)
    {
        return gfc->a * L + R;
    }
    else
    {
        return gfc->a * R + L;
    }
}

functions.fe_inv:
uint64_t fe_inv(const GFC *gfc, const uint64_t m)
{
    uint64_t L, R, tmp;
    if (gfc->r & 1)
    {
        R = m % gfc->a;
        L = m / gfc->a;
    }
    else
    {
        L = m % gfc->a;
        R = m / gfc->a;
    }
    for (uint64_t j = gfc->r; j >= 1; j--)
    {
        if (j & 1)
        {
            tmp = (R + gfc->a - (F(gfc, j, L) % gfc->a)) % gfc->a;
        }
        else
        {
            tmp = (R + gfc->b - (F(gfc, j, L) % gfc->b)) % gfc->b;
        }
        R = L;
        L = tmp;
    }
    return gfc->a * R + L;
}

functions.gfc_init:
GFC *gfc_init(uint64_t range, uint64_t rounds, uint64_t seed)
{
    GFC *gfc = calloc(1, sizeof(GFC));
    if (gfc == ((void *)0))
    {
        return ((void *)0);
    }
    gfc->M = range;
    gfc->r = rounds;
    const double tmp = ceil(sqrt((double)range));
    gfc->a = (uint64_t)tmp;
    gfc->b = (uint64_t)tmp;
    gfc->speck_exp = calloc(gfc->r * 27, sizeof(uint32_t));
    for (uint64_t i = 0; i < gfc->r; i++)
    {
        const uint64_t key[2] = {seed, i};
        speck_expand((const uint32_t *)key, gfc->speck_exp + i * 27);
    }
    return gfc;
}

functions.gfc_decrypt:
uint64_t gfc_decrypt(const GFC *gfc, const uint64_t m)
{
    uint64_t c = fe_inv(gfc, m);
    while (c >= gfc->M)
    {
        c = fe_inv(gfc, c);
    }
    return c;
}

functions.gfc_encrypt:
uint64_t gfc_encrypt(const GFC *gfc, const uint64_t m)
{
    uint64_t c = fe(gfc, m);
    while (c >= gfc->M)
    {
        c = fe(gfc, c);
    }
    return c;
}
